// HasFlow applies the HasEdge predicate on the "flow" edge.
func HasFlow() predicate.OAuthCompletionTicket {
	return predicate.OAuthCompletionTicket(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, FlowTable, FlowColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasFlowWith applies the HasEdge predicate on the "flow" edge with a given conditions (other predicates).
func HasFlowWith(preds ...predicate.OAuthFlow) predicate.OAuthCompletionTicket {
	return predicate.OAuthCompletionTicket(func(s *sql.Selector) {
		step := newFlowStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

