// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OAuthCompletionTicket) predicate.OAuthCompletionTicket {
	return predicate.OAuthCompletionTicket(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OAuthCompletionTicket) predicate.OAuthCompletionTicket {
	return predicate.OAuthCompletionTicket(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OAuthCompletionTicket) predicate.OAuthCompletionTicket {
	return predicate.OAuthCompletionTicket(sql.NotPredicates(p))
}
